lib:
if(pn)head+=`<span class="tn-o">${esc(xlab(l))}: ${pn}</span>`}}
    else head=`<span class="pn"><span class="pw">This sentence did not change between ${dlab(S.m.f.d)} and ${dlab(S.m.n.d)}.</span></span>`}
  h+=head+

if(pn)head+=`<span class="tn-o">${esc(heLang(l))}: ${pn}</span>`}}
    else head=`<span class="pn"><span class="pw">המשפט הזה לא השתנה בין ${heMY(S.m.f.d)} ל־${heMY(S.m.n.d)}.</span></span>`}
  head=hePw(head);if(head&&!/class="pw">המשפט/.test(head))head=`<div lang="en" dir="ltr">${head}</div>`;
  h+=head+

h+=isPhone()?`<details class="then"><summary><b>Then · ${dlab(S.m.f.d)}</b></summary><p>${tx}</p></details>`:`<p class="then"><b>Then · ${dlab(S.m.f.d)}:</b> ${tx}</p>`}
    if(en&&w==="n")h+=`<span class="src">English opening sections have changed since this copy; the story above quotes the 5 November 2026 text.</span>`}
  else if(c.x)h+=`<p class="why">${esc(c.x)}</p>`;
  else if(!A)h+=`<p class="why">No article in this language is linked to the English article.</p>`;
  if(A)h+=`<button type="button" class="go">Open the full sentence${S&&S.m.f&&S.m.n?", then and now":""} →</button>`;

h+=isPhone()?`<details class="then"><summary><b>אז · ${heMY(S.m.f.d)}</b></summary><p lang="${en||!Tf?l:"en"}" dir="${(en||!Tf)&&rtl?"rtl":"ltr"}">${tx}</p></details>`:`<p class="then"><b>אז · ${heMY(S.m.f.d)}:</b> <span lang="${en||!Tf?l:"en"}" dir="${(en||!Tf)&&rtl?"rtl":"ltr"}">${tx}</span></p>`}
    if(en&&w==="n")h+=`<span class="src">פתיחי הערכים באנגלית השתנו מאז העותק הזה; הכרטיסים למעלה מצטטים את נוסח 5 בנובמבר 2026.</span>`}
  else if(c.x)h+=`<p class="why">${esc(heX(c.x))}</p>`;
  else if(!A)h+=`<p class="why">אין בשפה הזאת ערך המקושר לערך באנגלית.</p>`;
  if(A)h+=`<button type="button" class="go">למשפט המלא${S&&S.m.f&&S.m.n?", אז ועכשיו":""}, בכלי הקריאה (באנגלית) ←</button>`;
